import os, json, numpy as np
from math import hypot
try:
    from scipy.optimize import minimize
except Exception:
    minimize = None

N = 26
R_MIN = 1e-6
SAFETY = 1e-9

AMPS = [0.03, 0.04, 0.05, 0.06]
SEEDS = [11, 23, 47, 89]  # 4 seeds per amp → 16 starts

# ----- Base seed: 5×5 grid + central cell-hole at (0.2,0.2) -----
def grid_plus_hole_centers():
    coords = np.array([0.1, 0.3, 0.5, 0.7, 0.9], dtype=float)
    centers = np.array([[x, y] for x in coords for y in coords], dtype=float)  # 25
    hole_center = np.array([0.2, 0.2], dtype=float)
    centers = np.vstack([centers, hole_center])
    return centers

# ----- Feasibility helpers -----
def boundary_caps(centers, eps=1e-9):
    x = centers[:,0]; y = centers[:,1]
    cap = np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y)) - eps
    return np.maximum(cap, R_MIN)

def make_feasible(centers, radii, eps=1e-9, max_iter=2000):
    c = centers.copy()
    r = np.minimum(radii.copy(), boundary_caps(c, eps=eps))
    r = np.maximum(r, R_MIN)
    for _ in range(max_iter):
        diff = c[:,None,:] - c[None,:,:]
        dist = np.sqrt(np.sum(diff**2, axis=2)) + 1e-15
        iu = np.triu_indices(N, 1)
        m = dist[iu] - (r[iu[0]] + r[iu[1]])
        if np.all(m >= eps):
            break
        k = int(np.argmin(m))
        i, j = iu[0][k], iu[1][k]
        need = (r[i] + r[j] - dist[i, j]) + eps
        di = min(need * 0.5, r[i] - R_MIN)
        dj = min(need - di, r[j] - R_MIN)
        if di <= 0 and dj <= 0:
            r = np.maximum(r * 0.999, R_MIN)
        else:
            r[i] -= di; r[j] -= dj
        r = np.minimum(r, boundary_caps(c, eps=eps))
    r = np.maximum(r - SAFETY, R_MIN)
    return c, r

# ----- SLSQP model with analytic Jacobians -----
def pack_to_z(c, r):
    Z = np.zeros((N,3), float); Z[:,:2] = c; Z[:,2] = r; return Z.ravel()

def z_to_pack(z):
    Z = np.array(z, float).reshape(N,3); return Z[:,:2], Z[:,2]

def obj(z): return -np.sum(z[2::3])
def obj_jac(z):
    g = np.zeros_like(z); g[2::3] = -1.0; return g

def ineq_boundary(z):
    Z = np.array(z,float).reshape(N,3)
    x = Z[:,0]; y = Z[:,1]; r = Z[:,2]
    return np.concatenate([x - r, 1.0 - x - r, y - r, 1.0 - y - r])

def jac_boundary(z):
    J = np.zeros((4*N, 3*N), float)
    for i in range(N):
        xi = 3*i; yi = xi+1; ri = xi+2
        J[i, xi]       = 1.0;  J[i, ri]       = -1.0
        J[N+i, xi]     = -1.0; J[N+i, ri]     = -1.0
        J[2*N+i, yi]   = 1.0;  J[2*N+i, ri]   = -1.0
        J[3*N+i, yi]   = -1.0; J[3*N+i, ri]   = -1.0
    return J

def ineq_pairs(z):
    Z = np.array(z,float).reshape(N,3)
    c = Z[:,:2]; r = Z[:,2]
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    iu = np.triu_indices(N,1)
    return dist[iu] - (r[iu[0]] + r[iu[1]])

def jac_pairs(z):
    Z = np.array(z,float).reshape(N,3)
    c = Z[:,:2]
    m = N*(N-1)//2
    J = np.zeros((m, 3*N), float)
    idx = 0
    for i in range(N):
        xi = 3*i; yi = xi+1; ri = xi+2
        for j in range(i+1, N):
            xj = 3*j; yj = xj+1; rj = xj+2
            dx = c[i,0]-c[j,0]; dy = c[i,1]-c[j,1]
            d = hypot(dx, dy)
            if d < 1e-12:
                gx_i=gy_i=gx_j=gy_j = 0.0
            else:
                inv = 1.0/d
                gx_i = dx*inv; gy_i = dy*inv
                gx_j = -gx_i;   gy_j = -gy_i
            J[idx, xi] = gx_i; J[idx, yi] = gy_i; J[idx, ri] = -1.0
            J[idx, xj] = gx_j; J[idx, yj] = gy_j; J[idx, rj] = -1.0
            idx += 1
    return J

def is_feasible(z, tol=0.0):
    return (np.all(ineq_boundary(z) >= -tol) and np.all(ineq_pairs(z) >= -tol))

def slsqp_polish(c, r, maxiter=500, ftol=1e-9):
    if minimize is None: return make_feasible(c, r)
    z0 = pack_to_z(c, r)
    bounds = []
    for _ in range(N):
        bounds.extend([(0.0,1.0),(0.0,1.0),(R_MIN,0.5)])
    cons = [{'type':'ineq','fun':ineq_boundary,'jac':jac_boundary},
            {'type':'ineq','fun':ineq_pairs,'jac':jac_pairs}]
    try:
        res = minimize(obj, z0, method='SLSQP', jac=obj_jac,
                       bounds=bounds, constraints=cons,
                       options={'maxiter':maxiter,'ftol':ftol,'disp':False})
    except Exception:
        res = None
    if res is not None and res.success and is_feasible(res.x, tol=1e-12):
        c_star, r_star = z_to_pack(res.x)
        return make_feasible(c_star, r_star)
    return make_feasible(c, r)

# ----- Starts: uniform radii with feasibility clamp; center jitters near 0.04 -----
def jitter_seed(base_c, amp, rng):
    c = base_c.copy()
    c = np.clip(c + rng.uniform(-amp, amp, size=c.shape), 0.0, 1.0)
    # Uniform radii like Inquire's approach, but clamp to be feasible initially
    r0 = np.full(N, 0.05, dtype=float)
    cap = boundary_caps(c, eps=1e-9)
    r0 = np.minimum(r0, np.maximum(cap - 1e-12, R_MIN))
    return make_feasible(c, r0)

def construct_packing():
    base_c = grid_plus_hole_centers()

    best_c, best_r, best_s = None, None, -1.0
    logs = {'starts': []}

    for amp in AMPS:
        for s in SEEDS:
            rng = np.random.default_rng(s)
            c0, r0 = jitter_seed(base_c, amp, rng)
            c_opt, r_opt = slsqp_polish(c0, r0)
            ssum = float(np.sum(r_opt))
            logs['starts'].append({'amp': amp, 'seed': s, 'sum': ssum})
            if ssum > best_s + 1e-12:
                best_c, best_r, best_s = c_opt, r_opt, ssum

    # Save best and logs
    try:
        os.makedirs('storage/noesis/exports', exist_ok=True)
        if best_c is not None:
            np.savetxt('storage/noesis/latest_centers.txt', best_c, fmt='%.9f')
            np.savetxt('storage/noesis/latest_radii.txt',   best_r, fmt='%.9f')
        with open('storage/noesis/exports/uniform_radii_basin_log.json','w') as f:
            json.dump({'best_sum': best_s, 'starts': logs['starts']}, f, indent=2)
    except Exception:
        pass

    if best_c is None:
        # Fallback to base seed with tiny safe radii
        c_fb = grid_plus_hole_centers()
        r_fb = np.full(N, 0.02, dtype=float)
        c_fb, r_fb = make_feasible(c_fb, r_fb)
        return c_fb.astype(float), r_fb.astype(float)

    return np.array(best_c, float), np.array(best_r, float)
